async function circleRequest(query = "", payload, signal) {
  const options = {cache:"no-store", signal: signal || AbortSignal.timeout(15000)};
  if (payload) Object.assign(options, {
    method:"POST", headers:{"Content-Type":"application/json"}, body:JSON.stringify(payload)
  });
  const response = await fetch("/api/phone/circles" + query, options);
  if (response.status === 401) throw Error("请重新登录便签");
  if (!response.ok) {
    const detail = await response.json().catch(() => ({}));
    throw Error(detail.error || "暂时没有连上，请重试");
  }
  return response.json();
}

